    public static function export_csv(): void {
        if ((!current_user_can('bcrm_reports') && !current_user_can('bcrm_manage_cases')) || !check_admin_referer('bcrm_export_final_safe_set_csv')) wp_die('دسترسی غیرمجاز است.');
        @set_time_limit(0); nocache_headers(); header('Content-Type: text/csv; charset=UTF-8'); header('Content-Disposition: attachment; filename="bcrm-final-safe-set-v0.8.46-'.gmdate('Ymd-His').'.csv"');
        $o=fopen('php://output','wb'); fwrite($o,"\xEF\xBB\xBF"); fputcsv($o,['old_internal_id','old_customer_id','old_name','corrected_target','proposed_final_customer_id','destination_strategy','manifest_class','source_human_total','target_human_total','source_human_after_v45','target_human_after_v45','manual_merge_events','merge_conflict','final_class','commit_allowed','protected_expert_override','reason']);
        self::run(function($r)use($o){fputcsv($o,array_values($r));}); fclose($o); exit;
    }
