        echo '<form method="post" action="'.esc_url(admin_url('admin-post.php')).'" style="display:inline-block;margin-left:8px">';wp_nonce_field('bcrm_run_final_safe_set');echo '<input type="hidden" name="action" value="bcrm_run_final_safe_set"><button class="button button-primary button-hero">ساخت Final Safe Set (Dry Run)</button></form>';
        if(is_array($r)&&!empty($r['ok'])){echo '<form method="post" action="'.esc_url(admin_url('admin-post.php')).'" style="display:inline-block">';wp_nonce_field('bcrm_export_final_safe_set_csv');echo '<input type="hidden" name="action" value="bcrm_export_final_safe_set_csv"><button class="button button-secondary">دانلود CSV کامل Final Safe Set</button></form>';} echo '</div>';
        if(!is_array($r))return;if(empty($r['ok'])){echo '<div class="notice notice-error inline"><p>'.esc_html($r['error']??'اجرا نشد').'</p></div>';return;}
        echo '<div class="bcrm-card"><h2>خلاصه Final Safe Set</h2><p>شروع: '.esc_html($r['started_at']).' — پایان: '.esc_html($r['finished_at']).'</p><div class="bcrm-grid">';
        $labels=['profiles'=>'پروفایل Manifest','auto_commit'=>'AUTO_COMMIT','preserve_commit'=>'PRESERVE_AND_COMMIT','block'=>'BLOCK','new_source_human'=>'فعالیت انسانی جدید روی Source بعد از v0.8.45','new_target_human'=>'فعالیت انسانی جدید روی Target بعد از v0.8.45','manual_merge_profiles'=>'پروفایل دارای Merge دستی','merge_conflicts'=>'Merge Conflict','blacklisted_final_ids'=>'Final ID ممنوع (باید صفر)','duplicate_final_id_conflicts'=>'Final ID conflict غیرمجاز (باید صفر)']; foreach($labels as $k=>$l)echo '<div class="bcrm-card"><strong>'.esc_html(number_format_i18n((int)($r['counts'][$k]??0))).'</strong><span>'.esc_html($l).'</span></div>';echo '</div></div>';
        if(!empty($r['samples'])){echo '<div class="bcrm-card"><h2>نمونه موارد محافظت/Block</h2><table class="widefat striped"><thead><tr><th>Old</th><th>Name</th><th>Target</th><th>Final</th><th>Class</th><th>New Human</th><th>Merge</th><th>Reason</th></tr></thead><tbody>';foreach($r['samples'] as $x)echo '<tr><td>'.esc_html($x['old_customer_id']).'</td><td>'.esc_html($x['old_name']).'</td><td>'.esc_html($x['corrected_target']).'</td><td>'.esc_html($x['proposed_final_customer_id']).'</td><td><code>'.esc_html($x['final_class']).'</code></td><td>'.esc_html($x['source_human_after_v45']+$x['target_human_after_v45']).'</td><td>'.esc_html($x['manual_merge_events']).'</td><td>'.esc_html($x['reason']).'</td></tr>';echo '</tbody></table></div>';}
    }
    public static function stream_final_safe_set(callable $emit): array { @set_time_limit(0); return self::run($emit); }
    private static function run(?callable $emit): array {
        $res=['ok'=>false,'error'=>'','started_at'=>current_time('mysql'),'finished_at'=>'','counts'=>['profiles'=>0,'auto_commit'=>0,'preserve_commit'=>0,'block'=>0,'new_source_human'=>0,'new_target_human'=>0,'manual_merge_profiles'=>0,'merge_conflicts'=>0,'blacklisted_final_ids'=>0,'duplicate_final_id_conflicts'=>0],'samples'=>[]];
        if(!class_exists('Biawin_CRM_Replacement_Manifest')){$res['error']='Replacement Manifest در دسترس نیست.';return $res;}
        $plans=[];$ids=[];$mr=Biawin_CRM_Replacement_Manifest::stream_manifest(function($m)use(&$plans,&$ids){$old=(int)($m['old_internal_id']??0);if(!$old)return;$plans[$old]=$m;$ids[$old]=1;$ti=(int)($m['target_internal_id']??0);if($ti)$ids[$ti]=1;});if(empty($mr['ok'])){$res['error']='Manifest ساخته نشد.';return $res;}
        $activity=self::human_activity(array_keys($ids));$merges=self::merge_index($plans);$final_owner=[];
        foreach($plans as $old=>$m){$res['counts']['profiles']++;$ti=(int)($m['target_internal_id']??0);$sa=$activity[$old]??['total'=>0,'after'=>0];$ta=$ti?($activity[$ti]??['total'=>0,'after'=>0]):['total'=>0,'after'=>0];$mi=$merges[$old]??['events'=>0,'conflict'=>0];
            if($sa['after']>0)$res['counts']['new_source_human']++;if($ta['after']>0)$res['counts']['new_target_human']++;if($mi['events']>0)$res['counts']['manual_merge_profiles']++;if($mi['conflict'])$res['counts']['merge_conflicts']++;
            $final=(string)($m['proposed_final_customer_id']??'');$manifest=(string)($m['manifest_class']??'');$strategy=(string)($m['destination_strategy']??'');$cls='AUTO_COMMIT';$reason='فقط تغییرات سیستمی/مهاجرتی؛ بدون Evidence انسانی یا Merge دستی.';$override='';
            if($manifest==='AMBIGUOUS_MANUAL'||$strategy==='MANUAL_REVIEW'||$final===''){$cls='BLOCK';$reason='نگاشت یکتا نیست یا مقصد نهایی ندارد.';}
            elseif($mi['conflict']){$cls='BLOCK';$reason='Merge دستی چند مقصد اصلاحی متفاوت را دربر می‌گیرد.';}
            elseif($mi['events']>0){$cls='PRESERVE_AND_COMMIT';$override='MANUAL_MERGE';$reason='Merge/اتصال دستی کارشناس باید به‌عنوان Override حفظ شود.';}
            elseif($sa['total']>0||$ta['total']>0){$cls='PRESERVE_AND_COMMIT';$override='EXPERT_ACTIVITY';$reason=($sa['after']||$ta['after'])?'فعالیت انسانی جدید بعد از v0.8.45 شناسایی شد؛ Auto Commit متوقف شد.':'Evidence انسانی موجود است؛ Repair فقط با حفظ رکوردهای کارشناسی مجاز است.';}
            if($final!=='' && self::is_blacklisted($final)){$res['counts']['blacklisted_final_ids']++;$cls='BLOCK';$reason='Final CustomerID در Blacklist است.';}
            if($final!==''){if(isset($final_owner[$final])&&$final_owner[$final]!==$m['corrected_target']){$res['counts']['duplicate_final_id_conflicts']++;$cls='BLOCK';$reason='Final CustomerID به بیش از یک Corrected Target مستقل تخصیص یافته.';}else $final_owner[$final]=$m['corrected_target'];}
            $allow=$cls==='AUTO_COMMIT'?1:0;$res['counts'][strtolower($cls==='PRESERVE_AND_COMMIT'?'preserve_commit':$cls)]++;
            $row=['old_internal_id'=>$old,'old_customer_id'=>$m['old_customer_id']??'','old_name'=>$m['old_name']??'','corrected_target'=>$m['corrected_target']??'','proposed_final_customer_id'=>$final,'destination_strategy'=>$strategy,'manifest_class'=>$manifest,'source_human_total'=>$sa['total'],'target_human_total'=>$ta['total'],'source_human_after_v45'=>$sa['after'],'target_human_after_v45'=>$ta['after'],'manual_merge_events'=>$mi['events'],'merge_conflict'=>$mi['conflict'],'final_class'=>$cls,'commit_allowed'=>$allow,'protected_expert_override'=>$override,'reason'=>$reason];if($emit)$emit($row);if($cls!=='AUTO_COMMIT'&&count($res['samples'])<self::SAMPLE_LIMIT)$res['samples'][]=$row;
        }
        $res['ok']=true;$res['finished_at']=current_time('mysql');return $res;
    }
    private static function human_activity(array $ids): array {global $wpdb;$out=[];foreach($ids as $id)$out[$id]=['total'=>0,'after'=>0];$tables=['interactions'=>'agent_user_id','assignments'=>'assigned_by','activities'=>'actor_user_id','financial_cases'=>'created_by','service_cases'=>'created_by','customer_tags'=>'created_by','attachments'=>'uploaded_by','case_actions'=>'actor_user_id'];foreach($tables as $logical=>$actor){$t=Biawin_CRM_DB::table($logical);if(!self::table_exists($t)||!self::has($t,'customer_id')||!self::has($t,$actor))continue;$time=self::timecol($t);$rows=$wpdb->get_results("SELECT customer_id,$actor actor".($time?",$time tm":"")." FROM $t WHERE $actor IS NOT NULL AND $actor<>0",ARRAY_A);foreach((array)$rows as $r){$cid=(int)$r['customer_id'];if(!isset($out[$cid]))continue;$out[$cid]['total']++;if($time&&!empty($r['tm'])&&strtotime($r['tm'])>strtotime(self::V45_SNAPSHOT))$out[$cid]['after']++;}}return $out;}
    private static function merge_index(array $plans): array {global $wpdb;$o=[];$t=Biawin_CRM_DB::table('merge_events');if(!self::table_exists($t))return $o;foreach((array)$wpdb->get_results("SELECT primary_customer_id,merged_customer_ids,performed_by FROM $t WHERE performed_by IS NOT NULL AND performed_by<>0",ARRAY_A) as $r){$ids=[];$p=(int)$r['primary_customer_id'];if($p)$ids[]=$p;$j=json_decode((string)$r['merged_customer_ids'],true);if(is_array($j))foreach($j as $x)if((int)$x)$ids[]=(int)$x;$targets=[];foreach($ids as $id)if(isset($plans[$id])&&!empty($plans[$id]['corrected_target']))$targets[$plans[$id]['corrected_target']]=1;$conf=count($targets)>1?1:0;foreach($ids as $id){if(!isset($o[$id]))$o[$id]=['events'=>0,'conflict'=>0];$o[$id]['events']++;if($conf)$o[$id]['conflict']=1;}}return $o;}
    private static function is_blacklisted($id){static $set=null;if($set===null){$set=[];$p=BIAWIN_CRM_DIR.'data/blacklisted-customer-ids.txt';if(is_readable($p))foreach(file($p,FILE_IGNORE_NEW_LINES|FILE_SKIP_EMPTY_LINES) as $x)$set[strtoupper(trim($x))]=1;}return isset($set[strtoupper(trim((string)$id))]);}
    private static function table_exists($t){global $wpdb;return (string)$wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s',$t))===$t;}private static function cols($t){global $wpdb;$o=[];foreach((array)$wpdb->get_results("SHOW COLUMNS FROM `$t`",ARRAY_A) as $r)$o[$r['Field']]=1;return $o;}private static function has($t,$c){$x=self::cols($t);return isset($x[$c]);}private static function timecol($t){$x=self::cols($t);foreach(['created_at','assigned_at','updated_at'] as $c)if(isset($x[$c]))return $c;return '';}
}
